package com.vit.archds.service;
import com.fasterxml.jackson.databind.*; import com.vit.archds.entity.*; import com.vit.archds.dto.ProjectDtos.*; import com.vit.archds.repository.*; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class AnalysisService { private final AnalysisJobRepository jobs;private final ProjectService projects;private final RequirementRepository reqs;private final ArchitectureCandidateRepository candidates;private final OptimizationResultRepository optimizations;private final VerificationResultRepository verifications;private final RefinementIterationRepository refinements;private final ExplanationRepository explanations;private final ArchitectureDiagramRepository diagrams;private final AuditLogRepository audit;private final RestClient ai;private final ObjectMapper mapper; private final AnalysisWorker worker;
 public AnalysisService(AnalysisJobRepository j,ProjectService p,RequirementRepository r,ArchitectureCandidateRepository c,OptimizationResultRepository o,VerificationResultRepository v,RefinementIterationRepository ri,ExplanationRepository e,ArchitectureDiagramRepository d,AuditLogRepository a,RestClient ai,ObjectMapper m,AnalysisWorker w){jobs=j;projects=p;reqs=r;candidates=c;optimizations=o;verifications=v;refinements=ri;explanations=e;diagrams=d;audit=a;this.ai=ai;mapper=m;worker=w;}
 public AnalysisJob start(long projectId){Project p=projects.get(projectId);if(jobs.existsByProjectAndStatusIn(p,List.of(JobStatus.QUEUED,JobStatus.RUNNING)))throw new IllegalStateException("An analysis is already running for this project");reqs.findTopByProjectOrderByCreatedAtDesc(p).orElseThrow(()->new IllegalArgumentException("Save requirements before running analysis"));AnalysisJob j=jobs.save(new AnalysisJob(p));audit.save(new AuditLog(p.getOwner(),"ANALYSIS_QUEUED","PROJECT",String.valueOf(projectId)));worker.runAsync(j.getId());return j;}
 private List<String> split(String s){if(s==null||s.isBlank())return List.of();return Arrays.stream(s.split("\\r?\\n|;")).map(String::trim).filter(v->!v.isBlank()).toList();}private String safeMessage(Exception e){String m=e.getMessage();return m==null?"Unexpected analysis failure":m.length()>1800?m.substring(0,1800):m;}
 public AnalysisJob get(String jobId){AnalysisJob j=jobs.findByJobId(jobId).orElseThrow(()->new NoSuchElementException("Job not found"));projects.get(j.getProject().getId());return j;}public List<AnalysisJob> history(long projectId){Project p=projects.get(projectId);return jobs.findByProjectOrderByCreatedAtDesc(p);}public JsonNode result(long projectId){Project p=projects.get(projectId);AnalysisJob j=jobs.findByProjectOrderByCreatedAtDesc(p).stream().filter(x->x.getStatus()==JobStatus.COMPLETED&&x.getPipelineResponseJson()!=null).findFirst().orElseThrow(()->new NoSuchElementException("No completed analysis found"));try{return mapper.readTree(j.getPipelineResponseJson());}catch(Exception e){throw new IllegalStateException("Stored analysis result is invalid");}}
}
